import static org.jlinalg.cli.SaigeGrmInputs.*;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.genetics.PlinkBedDataset;

/** Typed hard-call association inputs, explicit cohort/allele choices and complete QC ledger. */
final class SaigeSingleInputs {
    private SaigeSingleInputs() { }
    record Spec(Path recipe,String recipeSha256,Map<?,?> source,Path modelBundle,Path prefix,String assembly,
                String chromosome,SaigeGenotypes.AlleleOrder alleleOrder,SaigeGenotypes.Missing imputation,
                double minMaf,double minMac,double maxMissing,double zeroCutoff,double zeroMac,boolean allowExtras,boolean excludeInvalid,
                boolean retainUnreportable,boolean firth,double firthCutoff,double spaCutoff,boolean fast,
                boolean centerOnly,double resamplingMac,int chunk,int threads,int maxSamples,int maxVariants,
                long maxBytes,long maxCells,long maxModelCells,long maxResultBytes) { }
    record Decision(String id,String chromosome,long position,String allele1,String allele2,String status,
                    SaigeGenotypes.Summary calls) { }
    record Prepared(Spec spec,SaigeModelBundle.Model model,Path prefix,Set<String> variants,List<Decision> decisions,
                    int sourceSamples,int[] cohort,int[] binary,Map<Path,String> immutable) {
        Prepared{variants=Collections.unmodifiableSet(new LinkedHashSet<>(variants));decisions=List.copyOf(decisions);cohort=cohort.clone();binary=binary==null?null:binary.clone();immutable=Map.copyOf(immutable);}
        @Override public int[] cohort(){return cohort.clone();}
        @Override public int[] binary(){return binary==null?null:binary.clone();}
        void verify()throws IOException {model.verify();for(var e:immutable.entrySet())if(!FollowupSupport.hash(e.getKey()).equals(e.getValue()))throw new IOException("Association source/snapshot changed: "+e.getKey());if(!FollowupSupport.hash(spec.recipe).equals(spec.recipeSha256))throw new IOException("Association recipe changed during execution");}
        PlinkBedDataset open()throws IOException {return PlinkBedDataset.open(prefix,variants,new PlinkBedDataset.Limits(spec.maxSamples,spec.maxVariants,spec.maxVariants,spec.maxBytes,1073741824L,16384),PlinkBedDataset.AllelePolicy.QC_ALLOW_MISSING);}
    }
    static Spec read(Path recipe)throws Exception {
        recipe=recipe.toAbsolutePath().normalize();if(!Files.isRegularFile(recipe)||Files.size(recipe)>2L*1048576)throw new IOException("Require a UTF8 association recipe at most 2MiB");byte[] raw=Files.readAllBytes(recipe);Map<?,?> root=map(SimpleJson.parse(StandardCharsets.UTF_8.newDecoder().decode(ByteBuffer.wrap(raw)).toString()));keys(root,Set.of("version","operation","model_bundle","genotypes","genotype_coding","assembly","allele_order","chromosome","cohort","qc","method","resources"));whole(root,"version",1,1);if(!text(root,"operation").equals("single"))throw new IOException("Require operation=single");if(!text(root,"genotype_coding").equals("diploid-autosomal-plink-bed"))throw new IOException("This association input profile requires explicit diploid-autosomal-plink-bed;BGEN/VCF integration remains separate work");String assembly=text(root,"assembly");if(assembly.chars().anyMatch(Character::isISOControl))throw new IOException("Assembly declaration contains a control character");String chromosome=text(root,"chromosome");int number;try{number=Integer.parseInt(chromosome);}catch(NumberFormatException failure){throw new IOException("Declare an exact chromosome string 1..22",failure);}if(number<1||number>22||!chromosome.equals(String.valueOf(number)))throw new IOException("Declare an exact chromosome string 1..22;no chromosome alias/ploidy conversion is inferred");
        SaigeGenotypes.AlleleOrder order=switch(text(root,"allele_order")){case "alt-first"->SaigeGenotypes.AlleleOrder.ALT_FIRST;case "ref-first"->SaigeGenotypes.AlleleOrder.REF_FIRST;default->throw new IOException("Declare alt-first or ref-first PLINK allele order");};Map<?,?> cohort=map(root.get("cohort"));keys(cohort,Set.of("extra_genotyped_samples"));String extras=text(cohort,"extra_genotyped_samples");if(!Set.of("error","allow-with-ledger").contains(extras))throw new IOException("Declare error or allow-with-ledger for extra genotype participants;every model IID is mandatory");
        Map<?,?> qc=map(root.get("qc"));keys(qc,Set.of("min_maf","min_mac","max_missing","imputation","invalid_marker_policy","dosage_zero_cutoff","dosage_zero_max_mac"));double maf=number(qc,"min_maf",0,.5),mac=number(qc,"min_mac",Double.MIN_NORMAL,2000000),missing=number(qc,"max_missing",0,1),zeroCutoff=number(qc,"dosage_zero_cutoff",0,2),zeroMac=number(qc,"dosage_zero_max_mac",0,2000000);SaigeGenotypes.Missing imputation=switch(text(qc,"imputation")){case "best_guess"->SaigeGenotypes.Missing.BEST_GUESS;case "mean"->SaigeGenotypes.Missing.MEAN;case "major-homozygote"->SaigeGenotypes.Missing.MAJOR_HOMOZYGOTE;default->throw new IOException("Declare best_guess,mean or major-homozygote imputation;the latter maps to original minor");};String invalid=text(qc,"invalid_marker_policy");if(!Set.of("error","exclude-with-ledger").contains(invalid))throw new IOException("Declare error or exclude-with-ledger for all-missing/unresolved-allele markers");
        Map<?,?> m=map(root.get("method"));keys(m,Set.of("firth_beta","firth_p_cutoff","spa_cutoff","fast_test","genotype_adjustment","resampling_max_mac","non_estimable"));boolean firth=SaigeModelBundle.booleanField(m,"firth_beta"),fast=SaigeModelBundle.booleanField(m,"fast_test");double firthCutoff=number(m,"firth_p_cutoff",0,1),spa=number(m,"spa_cutoff",0,100),resampling=number(m,"resampling_max_mac",0,1000000);String adjustment=text(m,"genotype_adjustment"),unreportable=text(m,"non_estimable");if(!Set.of("center-only-fast","project-covariates").contains(adjustment)||!Set.of("error","retain-with-ledger").contains(unreportable))throw new IOException("Declare genotype_adjustment=center-only-fast|project-covariates and non_estimable=error|retain-with-ledger");if(!fast&&adjustment.equals("center-only-fast"))throw new IOException("center-only-fast requires fast_test=true;otherwise original SAIGE forces covariate projection");
        Map<?,?> r=map(root.get("resources"));keys(r,Set.of("threads","variants_per_chunk","max_samples","max_variants","max_input_bytes","max_genotype_cells","max_model_cells","max_result_bytes"));int threads=(int)whole(r,"threads",1,64),chunk=(int)whole(r,"variants_per_chunk",1,1000000),samples=(int)optional(r,"max_samples",1000000,1,1000000),variants=(int)optional(r,"max_variants",1000000,1,5000000);long bytes=optional(r,"max_input_bytes",4L*1073741824,1,64L*1024*1073741824),cells=optional(r,"max_genotype_cells",1000000000,1,10000000000000L),model=optional(r,"max_model_cells",2000000,1,20000000),results=optional(r,"max_result_bytes",1073741824,1,16L*1073741824);
        return new Spec(recipe,java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(raw)),root,resolve(recipe,text(root,"model_bundle")),resolve(recipe,text(root,"genotypes")),assembly,chromosome,order,imputation,maf,mac,missing,zeroCutoff,zeroMac,extras.equals("allow-with-ledger"),invalid.equals("exclude-with-ledger"),unreportable.equals("retain-with-ledger"),firth,firthCutoff,spa,fast,adjustment.equals("center-only-fast"),resampling,chunk,threads,samples,variants,bytes,cells,model,results);
    }
    static Prepared prepare(Spec spec,Path work,SaigeRuntime.Context runtime)throws Exception {
        SaigeModelBundle.Model model=SaigeModelBundle.stage(spec.modelBundle,work,spec.assembly,Integer.parseInt(spec.chromosome),spec.maxBytes,spec.maxModelCells,runtime);if(model.ids().size()>spec.maxSamples)throw new IOException("Model sample count exceeds max_samples");if(model.trait().equals("quantitative")&&spec.firth)throw new IOException("Quantitative association cannot request binary Firth effects");if(spec.fast&&!spec.centerOnly&&!model.sparseRatio())throw new IOException("Original SAIGE disables requested fast_test without a sparse GRM and with projected genotypes;declare fast_test=false");
        Path inputs=work.resolve("inputs");Files.createDirectory(inputs);Path prefix=inputs.resolve("genotypes");var immutable=new LinkedHashMap<Path,String>();long bytes=0;for(String suffix:List.of(".bed",".bim",".fam")){Path file=Path.of(spec.prefix+suffix);if(!Files.isRegularFile(file))throw new IOException("Missing association genotype input: "+file);bytes=Math.addExact(bytes,Files.size(file));}if(bytes>spec.maxBytes||Files.getFileStore(work).getUsableSpace()<bytes+64L*1048576)throw new IOException("BED/BIM/FAM exceed max_input_bytes or available snapshot storage");
        for(String suffix:List.of(".bed",".bim",".fam")){Path source=Path.of(spec.prefix+suffix),target=Path.of(prefix+suffix);String digest=FollowupSupport.hash(source);Files.copy(source,target);if(!digest.equals(FollowupSupport.hash(target)))throw new IOException("Genotype source changed during association snapshot");immutable.put(source,digest);immutable.put(target,digest);}
        var allIds=new LinkedHashSet<String>();try(var reader=Files.newBufferedReader(Path.of(prefix+".bim"),StandardCharsets.UTF_8)){for(String line;(line=SaigeGrmInputs.line(reader,16384))!=null;){if(line.isBlank())continue;String[] fields=line.strip().split("[ \\t]+");if(fields.length!=6||allIds.size()>=spec.maxVariants||!allIds.add(fields[1]))throw new IOException("Association BIM requires unique IDs,six fields and bounded variant count");int chromosome;try{chromosome=Integer.parseInt(fields[0]);}catch(NumberFormatException failure){throw new IOException("This declared hard-call profile requires autosomes 1..22",failure);}if(chromosome<1||chromosome>22)throw new IOException("This association profile rejects nonautosomal source markers;no ploidy conversion is inferred");}}
        if(allIds.isEmpty())throw new IOException("No source variants");int[] y=null;if(model.trait().equals("binary")){double[] values=model.y();y=new int[values.length];for(int i=0;i<values.length;i++)y[i]=(int)values[i];}var decisions=new ArrayList<Decision>();var include=new ArrayList<String>();int sourceSamples;int[] cohort;
        try(var bed=PlinkBedDataset.open(prefix,allIds,new PlinkBedDataset.Limits(spec.maxSamples,spec.maxVariants,spec.maxVariants,spec.maxBytes,1073741824L,16384),PlinkBedDataset.AllelePolicy.QC_ALLOW_MISSING)){
            sourceSamples=bed.samples().size();cohort=SaigeGenotypes.cohortIndices(bed.samples(),model.ids());if(!spec.allowExtras&&sourceSamples!=model.ids().size())throw new IOException("Extra genotype participants require explicit allow-with-ledger");long cells=Math.multiplyExact((long)sourceSamples,allIds.size());if(cells>spec.maxCells)throw new IOException("Association genotype work exceeds max_genotype_cells");var modelPosition=new HashMap<String,Integer>();for(int i=0;i<model.ids().size();i++)modelPosition.put(model.ids().get(i),i);try(var writer=Files.newBufferedWriter(work.resolve("genotype-sample-ledger.tsv"),StandardCharsets.UTF_8)){writer.write("IID\tgenotype_index\tmodel_index\tstatus\n");for(int i=0;i<bed.samples().size();i++){String id=bed.samples().get(i).individualId();Integer position=modelPosition.get(id);writer.write(id+"\t"+i+"\t"+(position==null?"":position)+"\t"+(position==null?"extra-not-analyzed":"model-participant")+"\n");}}
            for(var variant:bed.selectedVariants()){
                if(!variant.chromosome().equals(spec.chromosome)){decisions.add(new Decision(variant.id(),variant.chromosome(),variant.position(),variant.allele1(),variant.allele2(),"excluded-other-chromosome",null));continue;}
                double[] source=bed.readAllele1Dosages(variant),selected=new double[cohort.length];int observed=0;for(int i=0;i<cohort.length;i++){selected[i]=source[cohort[i]];if(!Double.isNaN(selected[i]))observed++;}
                if(!variant.resolvedAlleles()||observed==0){String reason=observed==0?"all-model-calls-missing":"unresolved-alleles";if(!spec.excludeInvalid)throw new IOException("Invalid association marker "+variant.id()+": "+reason);decisions.add(new Decision(variant.id(),variant.chromosome(),variant.position(),variant.allele1(),variant.allele2(),"excluded-"+reason,null));continue;}
                SaigeGenotypes.Summary calls=SaigeGenotypes.calculatePlink(selected,y,spec.alleleOrder,spec.imputation,spec.zeroCutoff,spec.zeroMac).summary();double postMac=Math.min(calls.alleleCount(),2.0*calls.samples()-calls.alleleCount());String reason=calls.missingRate()>spec.maxMissing?"excluded-missingness":Math.min(calls.upstreamQcFrequency(),1-calls.upstreamQcFrequency())<spec.minMaf?"excluded-initial-maf":calls.upstreamQcMinorCount()<spec.minMac?"excluded-initial-mac":Math.min(calls.frequency(),1-calls.frequency())<spec.minMaf?"excluded-post-imputation-maf":postMac<spec.minMac?"excluded-post-imputation-mac":"eligible";decisions.add(new Decision(variant.id(),variant.chromosome(),variant.position(),variant.allele1(),variant.allele2(),reason,calls));include.add(variant.id());
            }
        }
        try(var writer=Files.newBufferedWriter(work.resolve("variant-ledger.tsv"),StandardCharsets.UTF_8)){writer.write("MarkerID\tCHR\tPOS\tA1\tA2\tstatus\texact_observed_MAC\toriginal_floating_QC_MAC\toriginal_floating_QC_AF\tmissing_rate\tpost_imputation_MAC\tpost_imputation_AF\tmissing_minor_dosage_fill\n");for(Decision d:decisions){var s=d.calls;String values=s==null?"\t".repeat(6):s.rawMinorCount()+"\t"+s.upstreamQcMinorCount()+"\t"+s.upstreamQcFrequency()+"\t"+s.missingRate()+"\t"+Math.min(s.alleleCount(),2.0*s.samples()-s.alleleCount())+"\t"+s.frequency()+"\t"+s.imputedMinorDosage();writer.write(d.id+"\t"+d.chromosome+"\t"+d.position+"\t"+d.allele1+"\t"+d.allele2+"\t"+d.status+"\t"+values+"\n");}}
        if(decisions.stream().noneMatch(d->d.status.equals("eligible")))throw new IOException("No eligible association variants;inspect variant-ledger.tsv. Empty exit-0 output is not admitted");Path ids=inputs.resolve("requested-variants.txt");Files.writeString(ids,String.join("\n",include)+"\n",StandardCharsets.UTF_8);immutable.put(ids,FollowupSupport.hash(ids));var result=new Prepared(spec,model,prefix,allIds,decisions,sourceSamples,cohort,y,immutable);result.verify();return result;
    }
    static List<String> command(Prepared prepared,Path work)throws Exception {
        Spec s=prepared.spec;SaigeModelBundle.Model m=prepared.model;var command=new ArrayList<String>(List.of("--bedFile="+prepared.prefix+".bed","--bimFile="+prepared.prefix+".bim","--famFile="+prepared.prefix+".fam","--idstoIncludeFile="+work.resolve("inputs/requested-variants.txt"),"--AlleleOrder="+(s.alleleOrder==SaigeGenotypes.AlleleOrder.ALT_FIRST?"alt-first":"ref-first"),"--chrom="+s.chromosome,"--GMMATmodelFile="+m.directory().resolve("null-model.rda"),"--varianceRatioFile="+m.directory().resolve("variance-ratios.tsv"),"--SAIGEOutputFile="+work.resolve("original-associations.tsv"),"--LOCO="+rbool(m.loco()),"--minMAF="+s.minMaf,"--minMAC="+s.minMac,"--maxMissing="+s.maxMissing,"--impute_method="+s.imputation.upstream,"--is_imputed_data=FALSE","--minInfo=0","--is_Firth_beta="+rbool(s.firth),"--pCutoffforFirth="+s.firthCutoff,"--SPAcutoff="+s.spaCutoff,"--is_fastTest="+rbool(s.fast),"--is_noadjCov="+rbool(s.centerOnly),"--max_MAC_for_ER="+s.resamplingMac,"--markers_per_chunk="+s.chunk,"--nThreads="+s.threads,"--is_output_moreDetails=TRUE","--is_overwrite_output=TRUE"));
        Map<?,?> fit=map(prepared.model.recipe().get("parameters")),vr=map(fit.get("variance_ratio"));if("categorical".equals(vr.get("kind"))){command.add("--cateVarRatioMinMACVecExclude="+join((List<?>)vr.get("lower_exclusive")));command.add("--cateVarRatioMaxMACVecInclude="+join((List<?>)vr.get("upper_inclusive")));}
        if(m.sparseRatio()){command.add("--sparseGRMFile="+m.directory().resolve("grm.mtx"));command.add("--sparseGRMSampleIDFile="+m.directory().resolve("sample-ids.txt"));}command.add("--relatednessCutoff="+number(fit,"relatedness_cutoff",0,2));command.add("--dosage_zerod_cutoff="+s.zeroCutoff);command.add("--dosage_zerod_MAC_cutoff="+s.zeroMac);return List.copyOf(command);
    }
    private static long optional(Map<?,?> m,String name,long fallback,long min,long max)throws IOException{return m.containsKey(name)?whole(m,name,min,max):fallback;}
    private static Path resolve(Path recipe,String value)throws IOException {if(value.chars().anyMatch(Character::isISOControl))throw new IOException("Path contains a control character");Path path=Path.of(value);return (path.isAbsolute()?path:recipe.getParent().resolve(path)).toAbsolutePath().normalize();}
    private static String rbool(boolean value){return value?"TRUE":"FALSE";}
    private static String join(List<?> values){return String.join(",",values.stream().map(String::valueOf).toList());}
}
